import os

def walk_and_print(root, max_depth=5):
    depth = 0
    while depth < max_depth and root:
        if not root.endswith('/'):
            root += '/'

        print(f"{'  '*depth}{os.path.basename(root)}")
        items = sorted(os.listdir(root))[:10]
        for item in items:
            full = root + item
            if os.path.isdir(full):
                next_root = full.rstrip('/')
                depth += 1
                print(next_root)
                if depth >= max_depth:
                    return

        # Find JSON files
        for item in sorted(os.listdir(root)):
            if item.endswith('.json'):
                print(f"  JSON: {root}/{item}")

        break

